Lemma w4s33_pre : forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x20 x22 x24 x25 x26 x27 x28 x29 x30 x31 : word)
         (P PE PP BITS tl mtl : Z),
    0 <= PP <= PE ->
    PE < 2^47 ->
    0 <= BITS < 2^64 ->
    1 <= tl <= 12 ->
    1 <= mtl <= 12 ->
    (PE - PP < 4 -> forall (y11 y13 : word),
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 (Z_to_bv 64 PP) x8 x9 x10 y11 x12 y13 x14 x15 x16 x17 x18
           (Z_to_bv 64 BITS) x20 (Z_to_bv 64 (tl + 256 * mtl)) x22 (Z_to_bv 64 PE) x24 x25 x26 x27 x28 x29 x30 x31) F
           (Z_to_bv 64 0x926fc) fc None mm (seg_rom asegs))) ->
    (4 <= PE - PP -> 64 < BITS -> forall (y11 y13 y17 : word),
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 (Z_to_bv 64 PP) x8 x9 x10 y11 x12 y13 x14 x15 x16 y17 x18
           (Z_to_bv 64 BITS) x20 (Z_to_bv 64 (tl + 256 * mtl)) x22 (Z_to_bv 64 PE) x24 x25 x26 x27 x28 x29 x30 x31) F
           (Z_to_bv 64 0x92864) fc None mm (seg_rom asegs))) ->
    (4 <= PE - PP -> BITS <= 64 -> forall (y13 : word),
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (PE + -3)) (Z_to_bv 64 (64 - tl)) (Z_to_bv 64 PP) x8 x9
           x10 (Z_to_bv 64 PP) x12 y13 x14 x15 x16 (Z_to_bv 64 64) x18 (Z_to_bv 64 BITS) x20 (Z_to_bv 64 (tl + 256 *
           mtl)) x22 (Z_to_bv 64 PE) x24 x25 x26 x27 x28 x29 x30 x31) F (Z_to_bv 64 0x92404) fc None mm (seg_rom
           asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 (Z_to_bv 64 PP) x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18
        (Z_to_bv 64 BITS) x20 (Z_to_bv 64 (tl + 256 * mtl)) x22 (Z_to_bv 64 PE) x24 x25 x26 x27 x28 x29 x30 x31) F
        (Z_to_bv 64 0x923d8) fc None mm (seg_rom asegs)).
