Lemma w4s33_Hc : forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x20 x21 x22 x23 x25 x26 x27 x28 x29 x30 x31 : word)
         (P S3 PTR BITS PP : Z),
    rw_cells asegs mm (P + 192) [C8 (Z_to_bv 64 (S3 + 8))] ->
    mem_inv asegs mm ->
    rng RNG P 496 ->
    rng_aimg RNG ->
    0x10007fff8000 <= P ->
    P + 496 <= 2^47 ->
    S3 < PTR < S3 + 8 ->
    8 <= S3 ->
    S3 + 8 < 2^47 ->
    0 <= BITS <= 64 ->
    (S3 <= PTR - BITS / 8 -> evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 (Z_to_bv 64 PP) (Z_to_bv 64 S3) x9 x10 x11 x12 x13 (Z_to_bv 64
